      ctx.fillStyle = pg; ctx.beginPath(); ctx.moveTo(px + 10, py); ctx.lineTo(px + pw, py); ctx.lineTo(px + pw - 8, py + 26); ctx.lineTo(px, py + 26); ctx.closePath(); ctx.fill();
