      ctx.strokeText(s, W / 2, H / 2); const g = ctx.createLinearGradient(W / 2 - 200, 0, W / 2 + 200, 0); g.addColorStop(0, '#22e6ff'); g.addColorStop(0.5, '#ff4fd8'); g.addColorStop(1, '#ffd45c');
