    ctx.beginPath(); ctx.moveTo(x + 8, y); ctx.lineTo(x + s, y); ctx.lineTo(x + s, y + s - 8); ctx.lineTo(x + s - 8, y + s); ctx.lineTo(x, y + s); ctx.lineTo(x, y + 8); ctx.closePath(); ctx.stroke();
