    ctx.fillStyle = 'rgba(5,6,10,.82)'; ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,.28)'; ctx.lineWidth = 1; ctx.stroke();
    ctx.clip();
    const fx = w * k, gx = w * kg, x0 = flip ? x + w : x, dir = flip ? -1 : 1;
    // ghost (recent damage), then the live fill
