    const gr = e2.createLinearGradient(0, 0, 0, 128); gr.addColorStop(0, '#ffffff'); gr.addColorStop(0.45, '#6a7088'); gr.addColorStop(0.55, '#1a1c26'); gr.addColorStop(1, '#050507');
    e2.fillStyle = gr; e2.fillRect(0, 0, 256, 128);
